glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
in vec3 a_position;
in vec4 a_color;
in float a_dist;
out vec4 v_color;
out float v_dist;
out vec2 v_localPosition;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  pos = cc_matViewProj * cc_matWorld * pos;
  v_color = a_color;
  v_dist = a_dist;
  v_localPosition = a_position.xy;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec4 v_color;
in float v_dist;
in vec2 v_localPosition;
layout(std140) uniform WatercolorSpread {
  vec4 watercolorParams;
  vec4 watercolorSize;
  vec4 watercolorDirection;
};
float hash21 (vec2 p) {
  p = fract(p * vec2(123.34, 345.45));
  p += dot(p, p + 34.345);
  return fract(p.x * p.y);
}
float valueNoise (vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  local = local * local * (3.0 - 2.0 * local);
  return mix(
    mix(hash21(cell), hash21(cell + vec2(1.0, 0.0)), local.x),
    mix(hash21(cell + vec2(0.0, 1.0)), hash21(cell + vec2(1.0, 1.0)), local.x),
    local.y
  );
}
vec4 frag () {
  float progress = clamp(watercolorParams.x, 0.0, 1.0);
  float seed = watercolorParams.y;
  vec2 origin = clamp(watercolorParams.zw, vec2(0.001), vec2(0.999));
  vec2 size = max(watercolorSize.xy, vec2(1.0));
  vec2 uv = v_localPosition / size + vec2(0.5);
  vec2 gridSize = max(watercolorDirection.zw, vec2(1.0));
  vec2 direction = sign(watercolorDirection.xy);
  vec2 activeAxes = step(vec2(0.5), abs(direction));
  float activeAxisCount = max(activeAxes.x + activeAxes.y, 1.0);
  vec2 clampedUv = clamp(uv, vec2(0.0), vec2(0.9999));
  vec2 cell = floor(clampedUv * gridSize);
  vec2 originCell = floor(origin * gridSize);
  vec2 cellSteps = max((cell - originCell) * direction, vec2(0.0)) * activeAxes;
  float maxSteps = max(
    (gridSize.x - 1.0) * activeAxes.x + (gridSize.y - 1.0) * activeAxes.y,
    1.0
  );
  vec2 localCell = fract(clampedUv * gridSize);
  vec2 orientedLocal = mix(vec2(1.0) - localCell, localCell, step(vec2(0.0), direction));
  float localSweep = dot(orientedLocal, activeAxes) / activeAxisCount;
  float cascadeStep = cellSteps.x + cellSteps.y;
  float flowDistance = (cascadeStep + localSweep * 0.72) / (maxSteps + 0.72);
  float broadNoise = valueNoise(uv * 8.5 + seed * 19.0);
  float fiberNoise = valueNoise(vec2(uv.x * 31.0, uv.y * 17.0) - seed * 7.0);
  float fineNoise = valueNoise(uv * 48.0 + seed * 13.0);
  float settle = smoothstep(0.78, 1.0, progress);
  float turbulence = (
    (broadNoise * 2.0 - 1.0) * 0.055
    + (fiberNoise * 2.0 - 1.0) * 0.018
  ) * (1.0 - settle);
  float reveal = 1.0 - pow(1.0 - progress, 1.72);
  reveal = mix(reveal, 1.08, settle);
  float noisyDistance = flowDistance + turbulence;
  float paintMask = 1.0 - smoothstep(reveal - 0.028, reveal + 0.034, noisyDistance);
  paintMask = mix(paintMask, 1.0, settle);
  float wetEdge = 1.0 - smoothstep(0.012, 0.058, abs(noisyDistance - reveal));
  wetEdge *= 1.0 - smoothstep(0.72, 0.96, progress);
  float pigmentDensity = 0.965 + (broadNoise - 0.5) * 0.07 + (fineNoise - 0.5) * 0.035;
  vec3 pigment = clamp(v_color.rgb * pigmentDensity + vec3(0.012), vec3(0.0), vec3(1.0));
  vec3 wetEdgeColor = min(vec3(1.0), v_color.rgb * 0.72 + vec3(0.46));
  vec3 outputPigment = mix(pigment, wetEdgeColor, wetEdge * 0.88);
  float alpha = max(paintMask, wetEdge * 0.95) * v_color.a;
  vec4 outputColor = vec4(outputPigment, alpha);
  outputColor.rgb *= outputColor.a;
    float aa = fwidth(v_dist);
  outputColor *= 1.0 - smoothstep(-aa, 0.0, abs(v_dist) - 1.0);
  return outputColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

